import{_ as e,H as l,f as s,i as n}from"./chunks/framework.nyB-Xt5O.js";const y=JSON.parse('{"title":"KM 5. 分析方法论（Analysis Methods）","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-map/km-5-analysis-methods/index.md","filePath":"knowledge-map/km-5-analysis-methods/index.md","lastUpdated":1779798726000}'),i={name:"knowledge-map/km-5-analysis-methods/index.md"};function t(o,a,d,r,m,h){return l(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="km-5-分析方法论-analysis-methods" tabindex="-1">KM 5. 分析方法论（Analysis Methods） <a class="header-anchor" href="#km-5-分析方法论-analysis-methods" aria-label="Permalink to &quot;KM 5. 分析方法论（Analysis Methods）&quot;">​</a></h1><blockquote><p>分析方法论是数据分析师的核心实战工具集。从用户行为视角出发，本节覆盖漏斗分析、同期群、留存、分层、归因、异动检测、LTV 等经典方法，以及电商、内容、金融、SaaS 四大行业的专题分析场景。</p></blockquote><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ol><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/01-funnel">漏斗分析</a> — 转化率计算、流失节点识别、漏斗对比、开放 vs 闭合漏斗、步骤归因</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/02-cohort">同期群分析</a> — 时间/行为同期群定义、留存/收入/活跃度三类型、矩阵可视化与解读</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/03-retention">留存分析</a> — Day N / Rolling / Bracket 留存、留存曲线、幸存者分析、流失预测框架</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/04-user-segmentation">用户分层</a> — RFM 模型、K-Means 聚类分层、策略映射、动态 vs 静态分层</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/05-attribution">归因分析</a> — 末次/首次/线性/时间衰减/位置归因、Shapley Value、数据驱动模型、选型对比</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/06-anomaly-detection">异动分析</a> — 加乘拆解、贡献度下钻、同比/环比/同周对比、Z-Score / CUSUM 检测</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/07-ltv">LTV 分析</a> — 历史与预测 LTV、Pareto/NBD 与 BG/NBD 概念、LTV / CAC 比率、分层应用</li><li><a href="/data-analysis-learning/knowledge-map/km-5-analysis-methods/08-industry">行业专题分析场景</a> — 电商漏斗与复购、内容消费深度、金融 Vintage 分析、SaaS 健康度与扩展收入</li></ol><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li><a href="/data-analysis-learning/learning-paths/path-2-core/02-analysis-methods">学习路径：分析方法论</a> — 快速入门版本</li></ul>',6)])])}const p=e(i,[["render",t]]);export{y as __pageData,p as default};
